package leetcode.code75

import kotlin.math.max

fun main() {
    var s =
        ""
    val maxVowels = Sol6().maxVowels(s, 57373)
    println(maxVowels)
}

class Sol6 {
    fun maxVowels(s: String, k: Int): Int {
        // 모음문자의 최대 개수
        // k는 몇개씩 자를꺼냐에 대한거
        // 리턴은 k개씩 잘랐을때 오는 최대 모음 문자의 개수
        var max = 0
        val array = s.toCharArray()
        var count = 0
        for (i in 0 until k) {
            if (isVowel(array[i])) {
                count++
            }
        }
        max = count

        for (i in k until s.length) {
            if (isVowel(array[i])) {
                count++
            }
            if (isVowel(array[i - k])) {
                count--
            }
            max = max(count, max)
        }

        return max
    }

    private fun isVowel(c: Char) = c in "aeiou"
}